    assertFalse(mapItems.isEmpty());
    // delete user schema fullname
    plainSchemaDAO.delete("fullname");
    entityManager().flush();
    // check for schema deletion
    schema = plainSchemaDAO.find("fullname");
    assertNull(schema);
    plainSchemaDAO.clear();
    // check for mappings deletion
