    AuditLoggerName createFailure = new AuditLoggerName(AuditElements.EventCategoryType.PROPAGATION, AnyTypeKind.ANY_OBJECT.name().toLowerCase(), RESOURCE_NAME_DBSCRIPTED, "create", AuditElements.Result.FAILURE);
    AuditLoggerName updateSuccess = new AuditLoggerName(AuditElements.EventCategoryType.PROPAGATION, AnyTypeKind.ANY_OBJECT.name().toLowerCase(), RESOURCE_NAME_DBSCRIPTED, "update", AuditElements.Result.SUCCESS);
