        } catch (Exception e) {
            // ignore
        }
        try {
            auditService.delete(createFailure.toAuditKey());
        } catch (Exception e) {
            // ignore
        }
        try {
            auditService.delete(updateSuccess.toAuditKey());
        } catch (Exception e) {
            // ignore
        }
        try {
            auditService.delete(updateFailure.toAuditKey());
        } catch (Exception e) {
