@Test
public void webClientAsync() throws IOException {
    String boundary = "--batch_" + UUID.randomUUID().toString();
    // request async processing
    Response response = WebClient.create(ADDRESS).path("batch").header(HttpHeaders.AUTHORIZATION, "Bearer " + adminClient.getJWT()).header(RESTHeaders.PREFER, Preference.RESPOND_ASYNC).type(RESTHeaders.multipartMixedWith(boundary.substring(2))).post(requestBody(boundary));
    assertEquals(Response.Status.ACCEPTED.getStatusCode(), response.getStatus());
    assertTrue(response.getMediaType().toString().startsWith(RESTHeaders.multipartMixedWith(boundary.substring(2))));
    assertEquals(Preference.RESPOND_ASYNC.toString(), response.getHeaderString(RESTHeaders.PREFERENCE_APPLIED));
    URI monitor = response.getLocation();
    assertNotNull(monitor);
    WebClient client = WebClient.create(monitor).header(HttpHeaders.AUTHORIZATION, "Bearer " + adminClient.getJWT()).type(RESTHeaders.multipartMixedWith(boundary.substring(2)));
    AtomicReference<Response> holder = new AtomicReference<>();
    await().atMost(MAX_WAIT_SECONDS, TimeUnit.SECONDS).pollInterval(1, TimeUnit.SECONDS).until(() -> {
        try {
            holder.set(client.get());
            return holder.get().getStatus() != Response.Status.ACCEPTED.getStatusCode();
        } catch (Exception e) {
            return false;
        }
    });
    response = holder.get();
    assertEquals(Response.Status.OK.getStatusCode(), response.getStatus());
    assertTrue(response.getMediaType().toString().startsWith(RESTHeaders.multipartMixedWith(boundary.substring(2))));
    String body = IOUtils.toString((InputStream) response.getEntity(), StandardCharsets.UTF_8);
    LOG.debug("Batch response body:\n{}", body);
    check(BatchPayloadParser.parse(new ByteArrayInputStream(body.getBytes()), response.getMediaType(), new BatchResponseItem()));
    // check results again: removed since they were returned above
    response = WebClient.create(monitor).header(HttpHeaders.AUTHORIZATION, "Bearer " + adminClient.getJWT()).type(RESTHeaders.multipartMixedWith(boundary.substring(2))).get();
    assertEquals(Response.Status.NOT_FOUND.getStatusCode(), response.getStatus());
}

