    // 4. re-read group, verify that pattern was applied
    groupTO = groupService.read(groupTO.getKey());
    assertNotNull(groupTO);
    assertEquals("11.230", groupTO.getPlainAttr(doubleSchemaName).get().getValues().get(0));
