@Test
public void delete() {
    ImplementationTO implementationTO = new ImplementationTO();
    implementationTO.setKey(UUID.randomUUID().toString());
    implementationTO.setEngine(ImplementationEngine.JAVA);
    implementationTO.setType(IdMImplementationType.PULL_ACTIONS);
    implementationTO.setBody(TestPullActions.class.getName());
    implementationService.create(implementationTO);
    PullTaskTO pullTask = taskService.read(TaskType.PULL, AbstractTaskITCase.PULL_TASK_KEY, false);
    assertNotNull(pullTask);
    int before = pullTask.getActions().size();
    pullTask.getActions().add(implementationTO.getKey());
    taskService.update(TaskType.PULL, pullTask);
    pullTask = taskService.read(TaskType.PULL, AbstractTaskITCase.PULL_TASK_KEY, false);
    assertNotNull(pullTask);
    int after = pullTask.getActions().size();
    assertEquals(before + 1, after);
    // fails because the implementation is used
    try {
        implementationService.delete(implementationTO.getType(), implementationTO.getKey());
        fail("Unexpected");
    } catch (SyncopeClientException e) {
        assertEquals(e.getType(), ClientExceptionType.InUse);
    }
    pullTask.getActions().remove(implementationTO.getKey());
    taskService.update(TaskType.PULL, pullTask);
    implementationService.delete(implementationTO.getType(), implementationTO.getKey());
}

@Test
public void getJWTToken() throws ParseException, JOSEException {
    // Get the token
    SyncopeClient localClient = clientFactory.create(ADMIN_UNAME, ADMIN_PWD);
    AccessTokenService accessTokenService = localClient.getService(AccessTokenService.class);
    Response response = accessTokenService.login();
    String token = response.getHeaderString(RESTHeaders.TOKEN);
    assertNotNull(token);
    String expiration = response.getHeaderString(RESTHeaders.TOKEN_EXPIRE);
    assertNotNull(expiration);
    // Validate the signature
    SignedJWT jwt = SignedJWT.parse(token);
    jwt.verify(JWS_VERIFIER);
    assertTrue(jwt.verify(JWS_VERIFIER));
    Date now = new Date();
    // Verify the expiry header matches that of the token
    Date tokenDate = jwt.getJWTClaimsSet().getExpirationTime();
    assertNotNull(tokenDate);
    Date parsedDate = new Date(OffsetDateTime.parse(expiration).truncatedTo(ChronoUnit.SECONDS).toInstant().toEpochMilli());
    assertEquals(tokenDate, parsedDate);
    assertTrue(parsedDate.after(now));
    // Verify issuedAt
    Date issueTime = jwt.getJWTClaimsSet().getIssueTime();
    assertNotNull(issueTime);
    assertTrue(issueTime.before(now));
    // Validate subject + issuer
    assertEquals(ADMIN_UNAME, jwt.getJWTClaimsSet().getSubject());
    assertEquals(JWT_ISSUER, jwt.getJWTClaimsSet().getIssuer());
    // Verify NotBefore
    Date notBeforeTime = jwt.getJWTClaimsSet().getNotBeforeTime();
    assertNotNull(notBeforeTime);
    assertTrue(notBeforeTime.before(now));
}

