        Optional<RemediationTO> remediation = remediationService.list(new RemediationQuery.Builder().page(1).size(1000).build()).getResult().stream().filter(r -> "uid=pullFromLDAP,ou=People,o=isp".equalsIgnoreCase(r.getRemoteName())).findFirst();
        assertTrue(remediation.isPresent());
        assertEquals(AnyTypeKind.USER.name(), remediation.get().getAnyType());
        assertEquals(ResourceOperation.CREATE, remediation.get().getOperation());
        assertNotNull(remediation.get().getAnyCRPayload());
        assertNull(remediation.get().getAnyURPayload());
        assertNull(remediation.get().getKeyPayload());
        assertTrue(remediation.get().getError().contains("SyncopeClientCompositeException: {[RequiredValuesMissing [userId]]}"));
    } finally {
        resourceService.delete(ldap.getKey());
        cleanUpRemediations();
    }
}

