@Test
public void exportCSV() throws IOException {
    ReconciliationService service = adminClient.getService(ReconciliationService.class);
    Client client = WebClient.client(service);
    client.accept(RESTHeaders.TEXT_CSV);
    AnyQuery anyQuery = new AnyQuery.Builder().realm(SyncopeConstants.ROOT_REALM).fiql(SyncopeClient.getUserSearchConditionBuilder().is("username").equalTo("*ini").query()).page(1).size(1000).orderBy("username ASC").build();
    CSVPushSpec spec = new CSVPushSpec.Builder(AnyTypeKind.USER.name()).ignorePaging(true).field("username").field("status").plainAttr("firstname").plainAttr("surname").plainAttr("email").plainAttr("loginDate").build();
    Response response = service.push(anyQuery, spec);
    assertEquals(Response.Status.OK.getStatusCode(), response.getStatus());
    assertEquals("attachment; filename=" + SyncopeConstants.MASTER_DOMAIN + ".csv", response.getHeaderString(HttpHeaders.CONTENT_DISPOSITION));
    PagedResult<UserTO> users = userService.search(anyQuery);
    assertNotNull(users);
    MappingIterator<Map<String, String>> reader = new CsvMapper().readerFor(Map.class).with(CsvSchema.emptySchema().withHeader()).readValues((InputStream) response.getEntity());
    int rows = 0;
    for (; reader.hasNext(); rows++) {
        Map<String, String> row = reader.next();
        assertEquals(users.getResult().get(rows).getUsername(), row.get("username"));
        assertEquals(users.getResult().get(rows).getStatus(), row.get("status"));
        switch(row.get("username")) {
            case "rossini":
                assertEquals(spec.getNullValue(), row.get("email"));
                assertTrue(row.get("loginDate").contains(spec.getArrayElementSeparator()));
                break;
            case "verdi":
                assertEquals("verdi@syncope.org", row.get("email"));
                assertEquals(spec.getNullValue(), row.get("loginDate"));
                break;
            case "bellini":
                assertEquals(spec.getNullValue(), row.get("email"));
                assertFalse(row.get("loginDate").contains(spec.getArrayElementSeparator()));
                break;
            default:
                break;
        }
    }
    assertEquals(rows, users.getTotalCount());
}

