    // ----------------------------------
    UserCR userCR = UserITCase.getUniqueSample("260@a.com");
    userCR.getAuxClasses().add(newClass.getKey());
    userCR.getVirAttrs().add(attr(virSchema.getKey(), "virtualvalue"));
    userCR.getResources().add(RESOURCE_NAME_WS2);
