    // ----------------------------------
    StatusR statusR = new StatusR.Builder().key(userTO.getKey()).type(StatusRType.SUSPEND).build();
    userTO = userService.status(statusR).readEntity(new GenericType<ProvisioningResult<UserTO>>() {
    }).getEntity();
