@Test
public void addResponseHeader() {
    // 1. no mapping for URL
    webClient.get().uri("/addResponseHeader").exchange().expectStatus().isNotFound();
    // 2. stub for proxied URL
    stubFor(get(urlEqualTo("/addResponseHeader")).willReturn(aResponse()));
    // 3. create route configuration
    SRARouteTO route = new SRARouteTO();
    route.setKey("addResponseHeader");
    route.setTarget(URI.create("http://localhost:" + wiremockPort));
    route.getPredicates().add(new SRARoutePredicate.Builder().factory(SRARoutePredicateFactory.METHOD).args("GET").build());
    route.getPredicates().add(new SRARoutePredicate.Builder().factory(SRARoutePredicateFactory.PATH).args("/addResponseHeader").cond(SRARoutePredicateCond.AND).build());
    route.getFilters().add(new SRARouteFilter.Builder().factory(SRARouteFilterFactory.ADD_RESPONSE_HEADER).args("Hello,World").build());
    SyncopeCoreTestingServer.ROUTES.put(route.getKey(), route);
    routeRefresher.refresh();
    // 4. now mapping works for URL
    webClient.get().uri("/addResponseHeader").exchange().expectStatus().isOk().expectHeader().valueEquals("Hello", "World");
    // 5. update route configuration
    route.getFilters().clear();
    route.getFilters().add(new SRARouteFilter.Builder().factory(SRARouteFilterFactory.ADD_RESPONSE_HEADER).args("Hello,WorldZ").build());
    routeRefresher.refresh();
    // 6. mapping for URL is updated too
    webClient.get().uri("/addResponseHeader").exchange().expectStatus().isOk().expectHeader().valueEquals("Hello", "WorldZ");
    // 7. update route configuration again
    route.getFilters().clear();
    routeRefresher.refresh();
    // 8. mapping for URL is updated again
    webClient.get().uri("/addResponseHeader").exchange().expectStatus().isOk().expectHeader().doesNotExist("Hello");
}

